// Load Memory — persistent state from Supabase n8n_content_state table

const https = require('https');
const config = $('Configuration').first().json;
const supabaseUrl = config.supabase_url;
const supabaseKey = config.supabase_service_key;

const categories = [
  'market_insight',
  'build_log',
  'before_after',
  'founder_lesson',
  'product_tease',
  'technical_deep'
];

// Fetch state from Supabase
function supabaseGet(url, key) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const options = {
      hostname: parsed.hostname,
      path: parsed.pathname + parsed.search,
      method: 'GET',
      headers: {
        'apikey': key,
        'Authorization': 'Bearer ' + key,
        'Content-Type': 'application/json'
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); }
        catch { resolve(null); }
      });
    });
    req.on('error', () => resolve(null));
    req.end();
  });
}

let state = null;
if (supabaseUrl && supabaseKey) {
  try {
    const rows = await supabaseGet(
      supabaseUrl + '/rest/v1/n8n_content_state?select=*&limit=1',
      supabaseKey
    );
    state = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  } catch (e) {
    state = null;
  }
}

const postedHistory = state?.posted_history ?? [];
const rotationIndex = state?.rotation_index ?? 0;
const bannedHashes = state?.banned_hashes ?? [];
const stateId = state?.id ?? null;

const nextCategory = categories[rotationIndex % categories.length];

// Banned topics — battle-tested list
const bannedTopics = [
  '"Built in 30 minutes" or any variation implying the tool is trivially simple',
  '"Faith apps are terrible" or any negative comparisons to other app categories',
  '"Controversial opinion" / "Hot take" / "Unpopular opinion" openers',
  '"Follow along" / "Follow for more" / "unfiltered version" CTAs',
  '"Debugging nightmare" or exaggerated struggle narratives',
  '"Building something different" or vague differentiation claims',
  'Any hashtags (#BuildInPublic, #IndieHacker, #SaaS, etc.)',
  '"Thread \ud83e\uddf5" or thread-style posts',
  'Emoji-heavy posts (more than 2 emojis)'
];

return [{
  json: {
    categories,
    nextCategory,
    rotationIndex,
    postedHistory,
    bannedTopics,
    bannedHashes,
    stateId,
    categoryDescriptions: {
      market_insight: 'Share a finding about the marketing automation space. What are founders struggling with? What tools are failing them? What gap does Conduikt fill?',
      build_log: 'What you shipped today with Claude Code. Reference specific commits, features built, bugs squashed. Show the real work.',
      before_after: 'Show a website before/after the tool optimizes it. Concrete results, real transformations. If no screenshots available, describe the transformation vividly.',
      founder_lesson: 'Honest takes on building as a solo founder in Lagos. The reality of building a SaaS from Nigeria — infrastructure challenges, time zone arbitrage, unique perspective on global markets.',
      product_tease: 'Preview a specific feature with enough detail to intrigue. Make people want to try it. Show the UI, the workflow, the magic moment.',
      technical_deep: 'Architecture decisions, why Claude over GPT, Supabase patterns, Next.js 15 App Router insights, n8n automation patterns. Technical enough to impress, clear enough to follow.'
    }
  }
}];

// Prepare Inputs — decode base64 GitHub API content and merge all context
// Handles fetch node failures gracefully with fallback values

const config = $('Configuration').first().json;
const memory = $('Load Memory').first().json;

// Helper: safely decode base64 content from GitHub API responses
function decodeGitHubContent(nodeName) {
  try {
    const data = $(nodeName).first().json;
    // If the node failed (continueOnFail), data may be an error object
    if (data && data.error) return null;
    if (data && data.content) {
      const cleaned = data.content.replace(/\n/g, '');
      return Buffer.from(cleaned, 'base64').toString('utf-8');
    }
    return null;
  } catch (e) {
    return null;
  }
}

// Decode WORKPLAN.md — fallback: empty string
const workplan = decodeGitHubContent('Fetch WORKPLAN.md') || '';

// Decode CHANGELOG.md — fallback: empty string
const changelog = decodeGitHubContent('Fetch CHANGELOG.md') || '';

// Decode screenshots index.json — fallback: empty object
let screenshotsIndex = {};
try {
  const rawScreenshots = decodeGitHubContent('Fetch Screenshots Index');
  if (rawScreenshots) {
    screenshotsIndex = JSON.parse(rawScreenshots);
  }
} catch (e) {
  screenshotsIndex = {};
}

// Format recent commits — fallback: empty array representation
let formattedCommits = 'No recent commits available.';
try {
  const commitsData = $('Fetch Recent Commits').first().json;
  // Check for error response from continueOnFail
  if (commitsData && commitsData.error) {
    formattedCommits = 'No recent commits available.';
  } else {
    const commits = Array.isArray(commitsData) ? commitsData : (commitsData.data || [commitsData]);
    if (Array.isArray(commits) && commits.length > 0 && commits[0].sha) {
      formattedCommits = commits
        .slice(0, 10)
        .map((c, i) => {
          const sha = (c.sha || '').substring(0, 7);
          const message = c.commit ? c.commit.message : (c.message || 'No message');
          const date = c.commit ? c.commit.author.date : (c.date || '');
          return `${i + 1}. [${sha}] ${message.split('\n')[0]} (${date})`;
        })
        .join('\n');
    }
  }
} catch (e) {
  formattedCommits = 'No recent commits available.';
}

return [{
  json: {
    config,
    memory,
    workplan,
    changelog,
    recentCommits: formattedCommits,
    screenshotsIndex,
    nextCategory: memory.nextCategory,
    categoryDescription: memory.categoryDescriptions[memory.nextCategory]
  }
}];

// Construct Prompt — builds system instruction and user content SEPARATELY
// System instruction goes to Claude's system parameter, user content to messages

const data = $input.first().json;

const postedListStr = data.memory.postedHistory.length > 0
  ? data.memory.postedHistory.slice(-20).map(p => `- [${p.category}] ${p.summary} (${p.date})`).join('\n')
  : 'No previous posts yet.';

const bannedTopicsStr = data.memory.bannedTopics.join('\n- ');

// SYSTEM INSTRUCTION — everything about role, tone, rules, format
const systemInstruction = `You are the content voice for Conduikt — an AI marketing automation SaaS being built by a solo developer in Lagos, Nigeria using Claude Code.

Your audience: Technical founders, indie hackers, growth marketers on X and LinkedIn.

POST CATEGORY: ${data.nextCategory}

${data.categoryDescription}

TONE:
- Authentic builder voice — show the real work, not just highlights
- Technical enough to impress developers, clear enough for marketers
- Confident but not arrogant — you're building something real, not just hyping
- Nigerian founder perspective is a strength — lean into it naturally when relevant
- NO hashtags, NO "follow for more", NO generic motivation
- NO emojis overload — one or two max if they add meaning

PREVIOUSLY POSTED (DO NOT REPEAT THESE TOPICS OR ANGLES):
${postedListStr}

BANNED TOPICS (NEVER post about):
- ${bannedTopicsStr}

INSTRUCTIONS:
Generate 1 post for X (max 280 characters) and 1 adapted version for LinkedIn (400-700 characters).

The X post should be punchy, specific, and create curiosity or resonance.
The LinkedIn post should expand on the same idea with more context, paragraph breaks, and a professional/insight-driven tone.

If you reference an image_category, it MUST be one of the available screenshot categories listed above. If none are relevant, set image_category to null.

If you truly cannot generate a quality post that avoids duplicating previous content, set skip_reason to a brief explanation. Otherwise skip_reason must be null.

Output ONLY valid JSON (no markdown, no code fences, no explanation):
{
  "x_post": { "text": "...", "image_category": null },
  "linkedin_post": { "text": "...", "image_category": null },
  "category": "${data.nextCategory}",
  "skip_reason": null
}`;

// USER CONTENT — the actual context data for this run
const userContent = `RECENT COMMITS:
${data.recentCommits}

CURRENT WORKPLAN STATUS:
${data.workplan.substring(0, 3000)}

RECENT CHANGELOG:
${data.changelog.substring(0, 2000)}

AVAILABLE SCREENSHOT CATEGORIES: ${Object.keys(data.screenshotsIndex).join(', ') || 'none yet'}

Generate the content now.`;

return [{
  json: {
    systemInstruction,
    userContent,
    config: data.config,
    memory: data.memory,
    screenshotsIndex: data.screenshotsIndex
  }
}];

// Parse Response — extract JSON from Claude's response

const claudeResponse = $input.first().json;
const config = $('Construct Prompt').first().json.config;
const memory = $('Construct Prompt').first().json.memory;
const screenshotsIndex = $('Construct Prompt').first().json.screenshotsIndex;

let parsed = null;
let parseError = null;

try {
  // Claude returns content as an array of content blocks
  const textContent = claudeResponse.content
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('');

  // Try to parse the JSON directly
  try {
    parsed = JSON.parse(textContent);
  } catch (e) {
    // Sometimes Claude wraps JSON in code fences; strip them
    const jsonMatch = textContent.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[1].trim());
    } else {
      // Try to find JSON object in the response
      const objMatch = textContent.match(/\{[\s\S]*\}/);
      if (objMatch) {
        parsed = JSON.parse(objMatch[0]);
      } else {
        throw new Error('No JSON found in Claude response');
      }
    }
  }
} catch (e) {
  parseError = e.message;
  parsed = {
    x_post: { text: null, image_category: null },
    linkedin_post: { text: null, image_category: null },
    category: memory.nextCategory,
    skip_reason: 'Failed to parse Claude response: ' + e.message
  };
}

return [{
  json: {
    ...parsed,
    config,
    memory,
    screenshotsIndex,
    parseError
  }
}];

// Check Duplicate — compare against previously posted content and banned topics

const data = $input.first().json;
const postedHistory = data.memory.postedHistory || [];
const bannedTopics = data.memory.bannedTopics || [];
const xText = data.x_post ? data.x_post.text : null;

let isDuplicate = false;
let duplicateReason = null;

if (xText) {
  // Check for near-duplicate posts (simple similarity check)
  const xTextLower = xText.toLowerCase();

  for (const prev of postedHistory) {
    if (!prev.xText) continue;
    const prevLower = prev.xText.toLowerCase();

    // Check if more than 60% of words overlap
    const currentWords = new Set(xTextLower.split(/\s+/).filter(w => w.length > 3));
    const prevWords = new Set(prevLower.split(/\s+/).filter(w => w.length > 3));

    if (currentWords.size > 0 && prevWords.size > 0) {
      let overlap = 0;
      for (const word of currentWords) {
        if (prevWords.has(word)) overlap++;
      }
      const similarity = overlap / Math.max(currentWords.size, prevWords.size);
      if (similarity > 0.6) {
        isDuplicate = true;
        duplicateReason = `Too similar to previous post from ${prev.date}: "${prev.xText.substring(0, 80)}..." (${Math.round(similarity * 100)}% word overlap)`;
        break;
      }
    }
  }

  // Check banned topics
  if (!isDuplicate) {
    for (const banned of bannedTopics) {
      if (xTextLower.includes(banned.toLowerCase())) {
        isDuplicate = true;
        duplicateReason = `Contains banned topic: "${banned}"`;
        break;
      }
    }
  }
}

return [{
  json: {
    ...data,
    isDuplicate,
    duplicateReason,
    skip_reason: data.skip_reason || (isDuplicate ? duplicateReason : null)
  }
}];

// Log Skip — record why this run was skipped

const data = $input.first().json;

console.log(`[Conduikt Content Engine] SKIPPED`);
console.log(`  Category: ${data.category}`);
console.log(`  Skip reason: ${data.skip_reason}`);
console.log(`  Is duplicate: ${data.isDuplicate}`);
console.log(`  Parse error: ${data.parseError || 'none'}`);
console.log(`  Timestamp: ${new Date().toISOString()}`);

return [{
  json: {
    action: 'skipped',
    category: data.category,
    skip_reason: data.skip_reason,
    isDuplicate: data.isDuplicate,
    timestamp: new Date().toISOString()
  }
}];

// Select Image — match image_category to screenshots/index.json and pick a random image

const data = $input.first().json;
const screenshotsIndex = data.screenshotsIndex || {};

let selectedImage = null;
let imageUrl = null;

// Check X post image category first, then LinkedIn
const imageCategory = (data.x_post && data.x_post.image_category) || 
                      (data.linkedin_post && data.linkedin_post.image_category) || 
                      null;

if (imageCategory && screenshotsIndex[imageCategory]) {
  const images = screenshotsIndex[imageCategory];
  if (Array.isArray(images) && images.length > 0) {
    // Pick a random image from the category
    const randomIndex = Math.floor(Math.random() * images.length);
    selectedImage = images[randomIndex];

    // Construct the raw GitHub URL for the image
    const owner = data.config.repo_owner;
    const repo = data.config.repo_name;
    imageUrl = `https://raw.githubusercontent.com/${owner}/${repo}/master/screenshots/${imageCategory}/${selectedImage}`;
  }
}

return [{
  json: {
    ...data,
    selectedImage,
    imageUrl,
    imageCategory,
    hasImage: selectedImage !== null
  }
}];

// Log Dry Run — output what would have been posted

const data = $input.first().json;

const logOutput = {
  mode: 'DRY RUN',
  timestamp: new Date().toISOString(),
  category: data.category,
  x_post: data.x_post,
  linkedin_post: data.linkedin_post,
  selectedImage: data.selectedImage,
  imageUrl: data.imageUrl,
  hasImage: data.hasImage
};

console.log('=== CONDUIKT CONTENT ENGINE — DRY RUN ===');
console.log(JSON.stringify(logOutput, null, 2));
console.log('=========================================');

return [{
  json: logOutput
}];

// Sign OAuth for Media Tweet — construct OAuth 1.0a signature for Twitter API v2
// This node prepares the OAuth header for the tweet posting request with media

const crypto = require('crypto');

const data = $input.first().json;
const config = $('Configuration').first().json;
const postData = $('Select Image').first().json;

const mediaId = data.media_id_string || data.media_id;

// OAuth 1.0a parameters
const oauthParams = {
  oauth_consumer_key: config.twitter_api_key,
  oauth_nonce: crypto.randomBytes(16).toString('hex'),
  oauth_signature_method: 'HMAC-SHA1',
  oauth_timestamp: Math.floor(Date.now() / 1000).toString(),
  oauth_token: config.twitter_access_token,
  oauth_version: '1.0'
};

// Create signature base string
const method = 'POST';
const baseUrl = 'https://api.twitter.com/2/tweets';

const paramString = Object.keys(oauthParams)
  .sort()
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(oauthParams[k])}`)
  .join('&');

const signatureBase = `${method}&${encodeURIComponent(baseUrl)}&${encodeURIComponent(paramString)}`;

const signingKey = `${encodeURIComponent(config.twitter_api_secret)}&${encodeURIComponent(config.twitter_access_token_secret)}`;

const signature = crypto
  .createHmac('sha1', signingKey)
  .update(signatureBase)
  .digest('base64');

oauthParams.oauth_signature = signature;

const authHeader = 'OAuth ' + Object.keys(oauthParams)
  .sort()
  .map(k => `${encodeURIComponent(k)}="${encodeURIComponent(oauthParams[k])}"`)
  .join(', ');

return [{
  json: {
    authHeader,
    tweetText: postData.x_post.text,
    mediaId,
    hasMedia: true,
    fullPostData: postData
  }
}];

// Sign OAuth for Text-Only Tweet — construct OAuth 1.0a signature for Twitter API v2

const crypto = require('crypto');

const data = $input.first().json;
const config = $('Configuration').first().json;

// OAuth 1.0a parameters
const oauthParams = {
  oauth_consumer_key: config.twitter_api_key,
  oauth_nonce: crypto.randomBytes(16).toString('hex'),
  oauth_signature_method: 'HMAC-SHA1',
  oauth_timestamp: Math.floor(Date.now() / 1000).toString(),
  oauth_token: config.twitter_access_token,
  oauth_version: '1.0'
};

const method = 'POST';
const baseUrl = 'https://api.twitter.com/2/tweets';

const paramString = Object.keys(oauthParams)
  .sort()
  .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(oauthParams[k])}`)
  .join('&');

const signatureBase = `${method}&${encodeURIComponent(baseUrl)}&${encodeURIComponent(paramString)}`;

const signingKey = `${encodeURIComponent(config.twitter_api_secret)}&${encodeURIComponent(config.twitter_access_token_secret)}`;

const signature = crypto
  .createHmac('sha1', signingKey)
  .update(signatureBase)
  .digest('base64');

oauthParams.oauth_signature = signature;

const authHeader = 'OAuth ' + Object.keys(oauthParams)
  .sort()
  .map(k => `${encodeURIComponent(k)}="${encodeURIComponent(oauthParams[k])}"`)
  .join(', ');

return [{
  json: {
    authHeader,
    tweetText: data.x_post.text,
    hasMedia: false,
    fullPostData: data
  }
}];

// LinkedIn Adapter — prepare data for LinkedIn Community Management API

const data = $input.first().json;
let tweetResponse;
let fullPostData;

// Determine which path we came from (media or text-only)
try {
  tweetResponse = data;
  try {
    fullPostData = $('Sign OAuth (Media)').first().json.fullPostData;
  } catch(e) {
    try {
      fullPostData = $('Sign OAuth (Text Only)').first().json.fullPostData;
    } catch(e2) {
      fullPostData = $('Select Image').first().json;
    }
  }
} catch(e) {
  fullPostData = $input.first().json;
}

const linkedinText = fullPostData.linkedin_post ? fullPostData.linkedin_post.text : null;
const config = $('Configuration').first().json;
const tweetId = tweetResponse.data ? tweetResponse.data.id : null;

return [{
  json: {
    linkedinText,
    linkedinAccessToken: config.linkedin_access_token,
    linkedinPersonId: config.linkedin_person_id,
    tweetId,
    category: fullPostData.category,
    x_post: fullPostData.x_post,
    linkedin_post: fullPostData.linkedin_post,
    selectedImage: fullPostData.selectedImage,
    imageUrl: fullPostData.imageUrl,
    config
  }
}];

// Save State — persist to Supabase n8n_content_state table

const https = require('https');
const config = $('Configuration').first().json;
const supabaseUrl = config.supabase_url;
const supabaseKey = config.supabase_service_key;

// Gather post data from the flow
let postData;
try {
  postData = $('LinkedIn Adapter').first().json;
} catch(e) {
  try {
    postData = $('Log Dry Run').first().json;
  } catch(e2) {
    postData = $input.first().json;
  }
}

const isDryRun = config.dry_run;
const memory = $('Load Memory').first().json;

// Build updated history
const postedHistory = [...(memory.postedHistory || [])];

const record = {
  date: new Date().toISOString(),
  category: postData.category || 'unknown',
  xText: postData.x_post ? postData.x_post.text : null,
  linkedinText: postData.linkedin_post ? postData.linkedin_post.text : null,
  summary: postData.x_post ? postData.x_post.text.substring(0, 100) : 'No text',
  tweetId: postData.tweetId || null,
  imageUsed: postData.selectedImage || null,
  dryRun: isDryRun
};

postedHistory.push(record);

// Keep only last 100 entries
const trimmedHistory = postedHistory.slice(-100);
const nextRotationIndex = ((memory.rotationIndex || 0) + 1) % 6;

// Persist to Supabase
const stateId = memory.stateId;
if (stateId && supabaseUrl && supabaseKey) {
  try {
    const body = JSON.stringify({
      posted_history: trimmedHistory,
      rotation_index: nextRotationIndex,
      updated_at: new Date().toISOString()
    });
    const parsed = new URL(supabaseUrl + '/rest/v1/n8n_content_state?id=eq.' + stateId);
    await new Promise((resolve, reject) => {
      const options = {
        hostname: parsed.hostname,
        path: parsed.pathname + parsed.search,
        method: 'PATCH',
        headers: {
          'apikey': supabaseKey,
          'Authorization': 'Bearer ' + supabaseKey,
          'Content-Type': 'application/json',
          'Prefer': 'return=minimal',
          'Content-Length': Buffer.byteLength(body)
        }
      };
      const req = https.request(options, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => resolve(data));
      });
      req.on('error', reject);
      req.write(body);
      req.end();
    });
  } catch (e) {
    console.log('[Conduikt Content Engine] Failed to save state to Supabase: ' + e.message);
  }
}

console.log('[Conduikt Content Engine] State saved.');
console.log('  Category: ' + record.category);
console.log('  Dry run: ' + isDryRun);
console.log('  Next rotation index: ' + nextRotationIndex);
console.log('  Total posts in history: ' + trimmedHistory.length);

return [{
  json: {
    action: 'state_saved',
    record,
    nextRotationIndex,
    totalPostsInHistory: trimmedHistory.length,
    isDryRun
  }
}];
